#!/usr/bin/env python3
"""Generates the table-import fixtures used by src/tables/*.test.ts.

Run with a Python that has openpyxl installed (it is not an app dependency):

    python3 -m venv /tmp/tables-venv && /tmp/tables-venv/bin/pip install openpyxl
    /tmp/tables-venv/bin/python tests/fixtures/tables/make_fixtures.py

Outputs (next to this script):
  consequences.csv            UTF-8 with BOM, comma, CRLF (Excel "CSV UTF-8")
  consequences.tsv            UTF-16LE with BOM, tab (Excel "Unicode Text")
  consequences-semicolon.csv  UTF-8 without BOM, semicolon, decimal commas (European Excel)
  consequences-1256.csv       windows-1256 (Arabic Windows code page), comma
  consequences.xlsx           title rows above the header, plus an "Info" sheet and a hidden sheet
  consequences-clipboard.txt  Excel clipboard text/plain flavour (TSV, CRLF, quoted multi-line)
  consequences-clipboard.html Excel clipboard text/html flavour
  consequences-errors.csv     a table with deliberate errors (row validation)
  features.xlsx               dates/times, booleans, errors, formulas, rich text, sparse cells, Arabic sheet name
  dates1904.xlsx              1904 date system
All routes of the consequence table hold the same data and must import to identical tables.
"""

import csv
import datetime as dt
import html
import io
import os

import openpyxl
from openpyxl.cell.rich_text import CellRichText, TextBlock
from openpyxl.cell.text import InlineFont
from openpyxl.styles import Font
from openpyxl.utils.datetime import CALENDAR_MAC_1904

HERE = os.path.dirname(os.path.abspath(__file__))

HEADER = [
    'Tag',
    'Scenario',
    'Category',
    'X',
    'Y',
    'Radiation 4 kW/m2 (m)',
    'Radiation 12.5 kW/m2 (m)',
    'Radiation 37.5 kW/m2 (m)',
    'الوصف',
    'Notes',
]

CATEGORIES = [
    ('Jet fire', 'حريق نفاث'),
    ('Pool fire', 'حريق بركة'),
    ('Flash fire', 'حريق وميضي'),
    ('Fireball', 'كرة نارية'),
]
EQUIPMENT = ['P-101', 'P-102', 'V-201', 'V-202', 'T-301', 'C-401', 'E-501', 'K-601', 'R-701', 'D-801']
HOLES = [10, 25, 50]


def rows():
    out = []
    for i in range(30):
        tag = EQUIPMENT[i % len(EQUIPMENT)]
        hole = HOLES[(i // len(EQUIPMENT)) % len(HOLES)]
        cat, cat_ar = CATEGORIES[i % len(CATEGORIES)]
        x = round(100 + (i * 37.25) % 900, 2)
        y = round(50 + (i * 53.5) % 700, 2)
        r4 = round(20 + hole * 1.1 + (i % 7) * 2.5, 1)
        r12 = round(r4 * 0.62, 1)
        r37 = 'N/R' if i % 9 == 4 else round(r4 * 0.35, 1)
        ar = f'{cat_ar} عند {tag}'
        notes = ''
        if i == 3:
            notes = 'Line one\nLine two'
        elif i == 7:
            notes = 'Release of 12" line, see "Case B"'
        elif i == 11:
            notes = 'Wind 5 m/s, stability D'
        if i == 5:
            tag = f'  {tag} '  # stray spaces are trimmed by every route
        out.append([tag, f'{tag.strip()} {hole} mm leak', cat, x, y, r4, r12, r37, ar, notes])
    return out


def fmt_num(v, decimal_comma=False):
    if isinstance(v, (int, float)):
        s = repr(v) if isinstance(v, float) else str(v)
        if s.endswith('.0'):
            s = s[:-2]
        return s.replace('.', ',') if decimal_comma else s
    return v


def write_delimited(path, data, delimiter, encoding, bom=False, decimal_comma=False):
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=delimiter, lineterminator='\r\n', quoting=csv.QUOTE_MINIMAL)
    w.writerow(HEADER)
    for r in data:
        w.writerow([fmt_num(v, decimal_comma) for v in r])
    text = buf.getvalue()
    with open(path, 'wb') as f:
        if bom:
            f.write('\ufeff'.encode(encoding))
        f.write(text.encode(encoding))


def write_xlsx(path, data):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'Results'
    ws['A1'] = 'Consequence results — Unit 100'
    ws['A1'].font = Font(bold=True, size=14)
    ws.append([])
    ws.append(HEADER)
    for c in ws[3]:
        c.font = Font(bold=True)
    for r in data:
        ws.append([None if v == '' else v for v in r])
    ws.freeze_panes = 'A4'
    info = wb.create_sheet('Info')
    info.append(['Generated by', 'make_fixtures.py'])
    info.append(['Rows', len(data)])
    hidden = wb.create_sheet('Hidden calc')
    hidden.sheet_state = 'hidden'
    hidden.append(['secret', 1])
    wb.save(path)


def write_clipboard(path_txt, path_html, data):
    lines = []
    for r in [HEADER] + data:
        cells = []
        for v in r:
            s = fmt_num(v)
            if any(ch in s for ch in '\t\n'):
                s = '"' + s.replace('"', '""') + '"'
            cells.append(s)
        lines.append('\t'.join(cells))
    with open(path_txt, 'wb') as f:
        f.write(('\r\n'.join(lines) + '\r\n').encode('utf-8'))

    parts = [
        '<html xmlns:v="urn:schemas-microsoft-com:vml"\r\nxmlns:o="urn:schemas-microsoft-com:office:office"\r\n'
        'xmlns:x="urn:schemas-microsoft-com:office:excel"\r\nxmlns="http://www.w3.org/TR/REC-html40">\r\n'
        '<head>\r\n<meta http-equiv=Content-Type content="text/html; charset=utf-8">\r\n'
        '<meta name=ProgId content=Excel.Sheet>\r\n<style>\r\n<!--table\r\n\t{mso-displayed-decimal-separator:"\\.";}\r\n'
        '.xl65\r\n\t{mso-number-format:"0\\.0";}\r\n-->\r\n</style>\r\n</head>\r\n\r\n'
        '<body link="#0563C1" vlink="#954F72">\r\n\r\n'
        '<table border=0 cellpadding=0 cellspacing=0 width=960 style=\'border-collapse:\r\n collapse;width:720pt\'>\r\n'
        '<!--StartFragment-->\r\n <col width=64 span=10 style=\'width:48pt\'>\r\n'
    ]
    for r in [HEADER] + data:
        parts.append(' <tr height=20 style=\'height:15.0pt\'>\r\n')
        for v in r:
            if isinstance(v, (int, float)):
                parts.append(f'  <td height=20 class=xl65 align=right x:num="{fmt_num(v)}">{fmt_num(v)}</td>\r\n')
            elif v == '':
                parts.append('  <td></td>\r\n')
            else:
                body = html.escape(v, quote=False).replace('\n', "<br style='mso-data-placement:same-cell'>\r\n  ")
                body = body.replace('  P', '&nbsp; P') if v.startswith('  ') else body
                parts.append(f'  <td height=20 style=\'height:15.0pt\'>{body}</td>\r\n')
        parts.append(' </tr>\r\n')
    parts.append('<!--EndFragment-->\r\n</table>\r\n\r\n</body>\r\n\r\n</html>\r\n')
    with open(path_html, 'wb') as f:
        f.write(''.join(parts).encode('utf-8'))


def write_errors(path):
    data = [
        ['Tag', 'Scenario', 'X', 'Y', 'Radius (m)'],
        ['P-101', 'Valid row', 100, 200, 30],
        ['P-102', 'Missing X', '', 200, 25],
        ['P-103', 'Non-numeric Y', 110, 'abc', 25],
        ['P-104', 'Negative radius', 120, 220, -5],
        ['P-105', 'Non-numeric radius', 130, 230, 'twelve'],
        ['P-106', 'Zero radius', 140, 240, 0],
        ['P-107', 'Outside extent', 5000, 5000, 20],
        ['P-999', 'Unknown anchor', 150, 250, 15],
        ['', 'Missing anchor name', 160, 260, 10],
        ['P-110', 'Not reached', 170, 270, 'N/R'],
        ['P-111', 'Valid row', 180, 280, 12],
    ]
    with open(path, 'w', encoding='utf-8', newline='') as f:
        w = csv.writer(f, lineterminator='\n')
        for r in data:
            w.writerow(r)


def write_features(path):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'Types'
    ws.append(['Kind', 'Value'])
    ws.append(['date', dt.date(2024, 3, 15)])
    ws['B2'].number_format = 'yyyy-mm-dd'
    ws.append(['datetime', dt.datetime(2024, 3, 15, 13, 45, 30)])
    ws['B3'].number_format = 'dd/mm/yyyy hh:mm:ss'
    ws.append(['time', dt.time(6, 30, 0)])
    ws['B4'].number_format = 'h:mm'
    ws.append(['builtin14', dt.date(1999, 12, 31)])
    ws['B5'].number_format = 'mm-dd-yy'  # built-in id 14
    ws.append(['true', True])
    ws.append(['false', False])
    ws.append(['error', '#DIV/0!'])
    ws['B8'].data_type = 'e'
    ws.append(['formula', '=1+1'])
    ws.append(['float', 1234.5678])
    ws['B10'].number_format = '#,##0.00'
    ws.append(['percent', 0.125])
    ws['B11'].number_format = '0.0%'
    ws.append(['quoted unit', 42])
    ws['B12'].number_format = '0 "m"'
    ws.append(['rich', CellRichText([TextBlock(InlineFont(b=True), 'Bold'), ' and plain'])])
    ws.append(['entities', 'a < b & c > "d" \'e\''])
    ws.append(['arabic', 'مرحبا بالعالم'])
    ws.append(['big int', 12345678901])
    ws.append(['negative', -0.5])
    # Sparse: gap rows and columns.
    ws['A20'] = 'sparse'
    ws['D20'] = 7
    ws['F22'] = 'far'
    ws.merge_cells('A24:B24')
    ws['A24'] = 'merged'

    second = wb.create_sheet('بيانات')
    second.append(['اسم', 'قيمة'])
    second.append(['أ', 1])
    second.append(['ب', 2])
    wb.save(path)


def write_1904(path):
    wb = openpyxl.Workbook()
    wb.epoch = CALENDAR_MAC_1904
    ws = wb.active
    ws.title = 'Mac'
    ws.append(['Date'])
    ws.append([dt.date(2024, 3, 15)])
    ws['A2'].number_format = 'yyyy-mm-dd'
    wb.save(path)


def main():
    data = rows()
    write_delimited(os.path.join(HERE, 'consequences.csv'), data, ',', 'utf-8', bom=True)
    write_delimited(os.path.join(HERE, 'consequences.tsv'), data, '\t', 'utf-16-le', bom=True)
    write_delimited(os.path.join(HERE, 'consequences-semicolon.csv'), data, ';', 'utf-8', decimal_comma=True)
    write_delimited(os.path.join(HERE, 'consequences-1256.csv'), data, ',', 'cp1256')
    write_xlsx(os.path.join(HERE, 'consequences.xlsx'), data)
    write_clipboard(
        os.path.join(HERE, 'consequences-clipboard.txt'), os.path.join(HERE, 'consequences-clipboard.html'), data
    )
    write_errors(os.path.join(HERE, 'consequences-errors.csv'))
    write_features(os.path.join(HERE, 'features.xlsx'))
    write_1904(os.path.join(HERE, 'dates1904.xlsx'))


if __name__ == '__main__':
    main()
